component.css:
.cyber-alpha-container * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }
  .cyber-alpha-container {
    font-family: 'Courier New', monospace;
    max-width: 400px;
    width: 100%;
    margin: 0 auto;
    padding: 4px 0;
  }
  .cyber-panel-alpha {
    background: #0a0e1a;
    border: 2px solid #00f0ff;
    border-radius: 14px;
    padding: 20px 22px 22px 22px;
    box-shadow: 0 0 30px rgba(0, 240, 255, 0.12), inset 0 0 40px rgba(0, 240, 255, 0.03);
  }
  .cyber-header-alpha {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
  }
  .cyber-icon-alpha {
    font-size: 24px;
    color: #00f0ff;
    text-shadow: 0 0 12px #00f0ff88;
  }
  .cyber-title-alpha {
    font-size: 20px;
    font-weight: 700;
    letter-spacing: 2px;
    color: #c8ecff;
    text-shadow: 0 0 10px #00f0ff55;
    flex: 1;
  }
  .cyber-badge-alpha {
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1.5px;
    padding: 4px 12px;
    border-radius: 30px;
    background: #00f0ff22;
    border: 1px solid #00f0ffaa;
    color: #00f0ff;
    text-shadow: 0 0 6px #00f0ff66;
  }
  .cyber-divider-alpha {
    height: 2px;
    background: linear-gradient(90deg, transparent, #00f0ff77, transparent);
    margin: 14px 0 16px 0;
    border: none;
  }
  .cyber-body-alpha {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .cyber-text-alpha {
    font-size: 14px;
    line-height: 1.7;
    color: #aac2dd;
    letter-spacing: 0.3px;
  }
  .cyber-status-alpha {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 13px;
    color: #7a9abb;
  }
  .cyber-dot-alpha {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: #00ff88;
    box-shadow: 0 0 16px #00ff88aa;
    animation: cyber-pulse-alpha 1.6s ease-in-out infinite;
  }
  @keyframes cyber-pulse-alpha {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.3; transform: scale(0.8); }
  }
  .cyber-highlight-alpha {
    color: #00f0ff;
    font-weight: 600;
    text-shadow: 0 0 8px #00f0ff66;
  }
  .cyber-footer-alpha {
    margin-top: 18px;
    display: flex;
    justify-content: flex-end;
  }
  .cyber-btn-alpha {
    font-family: 'Courier New', monospace;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.8px;
    padding: 10px 24px;
    border-radius: 30px;
    border: none;
    cursor: pointer;
    transition: all 0.25s ease;
    text-transform: uppercase;
    background: transparent;
  }
  .cyber-btn-primary-alpha {
    background: #00f0ff22;
    border: 1.5px solid #00f0ff;
    color: #00f0ff;
    box-shadow: 0 0 16px transparent;
  }
  .cyber-btn-primary-alpha:hover {
    background: #00f0ff44;
    box-shadow: 0 0 32px #00f0ff44;
    transform: scale(1.03);
  }
  .cyber-btn-alpha:active {
    transform: scale(0.95);
  }

component.script:
(function() {
    var raw = getMsgContent() || '';
    var d = String.fromCharCode(36);

    function extract(tag) {
      var reg = new RegExp('<' + tag + '>([\\s\\S]*?)</' + tag + '>', 'i');
      var m = raw.match(reg);
      return m ? m[1].trim() : '';
    }

    var title = extract('title') || 'Alpha 终端';
    var subText = extract('subText') || '主链路已激活 · 数据加密通道稳定';

    setText('#alphaTitle', title);
    setText('#alphaSubText', subText);

    document.getElementById('alphaSwitchBtn').addEventListener('click', function() {
      var currentTitle = extract('title') || 'Alpha 终端';
      var currentSubText = extract('subText') || '主链路已激活 · 数据加密通道稳定';
      changeMsg(
        '<' + d + 'CyberPanelBeta' + d + '>' +
        '<title>' + currentTitle + '</title>' +
        '<subText>' + currentSubText + '</subText>' +
        '</' + d + 'CyberPanelBeta' + d + '>'
      );
    });
  })();
